const CORPUS_VERSION = "KJV-PCE-BP-2010-v1";
const ALGORITHM_VERSION = "1.1.0";
const CONFIG_SHA256 = "15eef95ae377a030daca0c63a6fa7f909fdbb74b581c828bb0799cdc4e711f8d";
const CONFIG_SHA256_BY_MATCH = { letter_exact:"da95ba66e2f60caa07f637c64b7b9c26ae957e59b1671a0ae0e0c20cd746adf9", exact_spelling:CONFIG_SHA256, normalized:"fbcee12bc8b95a6133d3dd44c72b65dc92f656bd2db7ca0ad9fec4c4b91e6c1e" };
const WORDNET_SOURCE = "https://wordnetcode.princeton.edu/3.0/WNdb-3.0.tar.gz";
const WORDNET_LICENSE = "WordNet 3.0 License — https://wordnet.princeton.edu/license-and-commercial-use";
const MODES = {
  reference: "Passage", "exact-word": "Exact word", "exact-phrase": "Exact phrase",
  related: "Related verses", compare: "Compare", graph: "Evidence graph",
  workflow: "WHGW workflows", topic: "Modern topic",
};
const HINTS = { reference:"John 3:16", "exact-word":"gathered", "exact-phrase":"in the beginning", related:"Isaiah 34:16", compare:"John 3:16\nRomans 5:8", graph:"John 3:16", workflow:"gathered", topic:"harmony" };
const BOOK_NAMES = ["Genesis","Exodus","Leviticus","Numbers","Deuteronomy","Joshua","Judges","Ruth","1 Samuel","2 Samuel","1 Kings","2 Kings","1 Chronicles","2 Chronicles","Ezra","Nehemiah","Esther","Job","Psalms","Proverbs","Ecclesiastes","Song of Solomon","Isaiah","Jeremiah","Lamentations","Ezekiel","Daniel","Hosea","Joel","Amos","Obadiah","Jonah","Micah","Nahum","Habakkuk","Zephaniah","Haggai","Zechariah","Malachi","Matthew","Mark","Luke","John","Acts","Romans","1 Corinthians","2 Corinthians","Galatians","Ephesians","Philippians","Colossians","1 Thessalonians","2 Thessalonians","1 Timothy","2 Timothy","Titus","Philemon","Hebrews","James","1 Peter","2 Peter","1 John","2 John","3 John","Jude","Revelation"];
const ALIASES = new Map();
BOOK_NAMES.forEach((name,index)=>{ const compact=name.toLowerCase().replaceAll(" ",""); for(const alias of [name,name.slice(0,3),compact]) ALIASES.set(alias.toLowerCase(),{book:name,bookOrder:index+1}); });
[["psalm","Psalms"],["ps","Psalms"],["gen","Genesis"],["ex","Exodus"],["lev","Leviticus"],["num","Numbers"],["deut","Deuteronomy"],["isa","Isaiah"],["jer","Jeremiah"],["matt","Matthew"],["mt","Matthew"],["mk","Mark"],["lk","Luke"],["jn","John"],["rev","Revelation"]].forEach(([a,n])=>ALIASES.set(a,{book:n,bookOrder:BOOK_NAMES.indexOf(n)+1}));

const state = { mode:"related", matchLevel:"exact_spelling", verses:[], stats:null, indexes:null, lastRecord:null, wordnet:null };
const $ = (selector)=>document.querySelector(selector);
const esc = (value)=>String(value).replace(/[&<>"']/g,(char)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[char]);
const label = (reference)=>`${reference.book} ${reference.chapter}:${reference.verse}`;
const compareRefs = (a,b)=>a.bookOrder-b.bookOrder||a.chapter-b.chapter||a.verse-b.verse;
const meta = (trace,matchLevel="exact_spelling")=>({ corpusVersion:CORPUS_VERSION, algorithmVersion:ALGORITHM_VERSION, configurationSha256:CONFIG_SHA256_BY_MATCH[matchLevel], queryTrace:trace });

function tokenize(text){ const tokens=[]; const pattern=/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu; for(const match of text.matchAll(pattern)){const surface=match[0]; tokens.push({position:tokens.length,charStart:match.index,charEnd:match.index+surface.length,surface,folded:surface.normalize("NFC").toLowerCase().replaceAll("’", "'")});} return tokens; }
function parseReference(input){ const match=/^(.+?)\s+(\d+):(\d+)(?:\s*[-–]\s*(?:(\d+):)?(\d+))?$/u.exec(input.trim()); if(!match) throw new Error(`Invalid reference syntax: ${input}`); const key=match[1].trim().replace(/\s+/g," ").toLowerCase(); const resolved=ALIASES.get(key)||BOOK_NAMES.map((book,i)=>({book,bookOrder:i+1})).find(x=>x.book.toLowerCase()===key); if(!resolved) throw new Error(`Unknown book: ${match[1]}`); const chapter=Number(match[2]),verse=Number(match[3]),endChapter=Number(match[4]||match[2]),endVerse=Number(match[5]||match[3]); if([chapter,verse,endChapter,endVerse].some(v=>!Number.isSafeInteger(v)||v<1)) throw new Error("Chapter and verse must be positive integers"); const start={...resolved,chapter,verse},end={...resolved,chapter:endChapter,verse:endVerse}; if(compareRefs(end,start)<0) throw new Error("Reference range ends before it starts"); return {start,end}; }

async function initialize(){
  try{
    const [corpusText,statsDocument]=await Promise.all([fetch("./data/kjv/verses.jsonl").then(requireOk).then(r=>r.text()),fetch("./data/kjv/statistics.json").then(requireOk).then(r=>r.json())]);
    state.verses=corpusText.trim().split("\n").map((line,id)=>{const row=JSON.parse(line);return {...row,id,tokens:tokenize(row.displayText)}});
    state.stats=statsDocument.statistics;
    state.indexes=buildIndexes(state.verses);
    renderTabs(); renderControls();
    $("#loading").hidden=true; $("#workbench").hidden=false;
  }catch(error){ $("#loading").innerHTML=`<strong>Could not prepare the research index.</strong><span>${esc(error.message)}</span>`; }
}
function requireOk(response){if(!response.ok) throw new Error(`Asset request failed (${response.status})`);return response;}
function buildIndexes(verses){ const word=new Map(),surface=new Map(),reference=new Map(); for(const verse of verses){reference.set(label(verse.reference),verse.id); for(const token of verse.tokens){for(const [index,key] of [[word,token.folded],[surface,token.surface]]){let posting=index.get(key);if(!posting){posting=new Map();index.set(key,posting);}let positions=posting.get(verse.id);if(!positions){positions=[];posting.set(verse.id,positions);}positions.push(token.position);}}} return {word,surface,reference}; }

function renderTabs(){ const root=$("#mode-tabs"); root.innerHTML=Object.entries(MODES).map(([value,text])=>`<button type="button" role="radio" aria-checked="${state.mode===value}" data-mode="${value}">${esc(text)}</button>`).join(""); root.querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>{state.mode=button.dataset.mode; $("#study-query").placeholder=HINTS[state.mode]; renderTabs(); renderControls(); clearResult();})); }
function renderControls(){ const root=$("#controls"); $("#notice").textContent=state.mode==="topic"?"Dictionary senses are external bridges. They never replace KJV wording or alter Scripture ranking.":state.mode==="related"?"Capitalization is edition-specific evidence in this corpus, not proof of interpretation or original-language meaning.":"Normalized matches are derived evidence; the displayed KJV wording is never replaced."; if(state.mode==="related"){root.innerHTML=`<fieldset class="filters"><legend>Candidate filters</legend><label>Strictness<select id="match-level"><option value="exact_spelling">Exact spelling</option><option value="letter_exact">Letter exact</option><option value="normalized">Normalized</option></select></label><label>Testament<select id="testament"><option value="">All</option><option value="OT">Old Testament</option><option value="NT">New Testament</option></select></label><label>Book<select id="book"><option value="">All books</option>${BOOK_NAMES.map(x=>`<option>${esc(x)}</option>`).join("")}</select></label><label>Minimum score<input id="minimum-score" type="number" min="0" max="1" step="0.01" value="0"></label><label>Evidence<select id="evidence"><option value="">All evidence</option><option value="shared_nonzero_token">Shared word</option><option value="shared_exact_phrase">Case-exact phrase</option><option value="shared_case_folded_phrase">Case-folded phrase</option><option value="shared_normalized_phrase">Normalized phrase</option></select></label></fieldset>`;$("#match-level").value=state.matchLevel;$("#match-level").addEventListener("change",event=>{state.matchLevel=event.target.value;});}else if(state.mode==="workflow") root.innerHTML=`<fieldset class="filters"><legend>Workflow</legend><label>Method<select id="workflow"><option value="gather_mentions">Gather mentions</option><option value="candidate_mates">Candidate mates</option><option value="divide_term">Divide term by book</option><option value="first_mention_chain">First-mention chain</option><option value="lexical_witnesses">Two witnesses</option></select></label></fieldset>`; else root.innerHTML=""; }
function clearResult(){state.lastRecord=null;$("#export-button").disabled=true;$("#result-title").textContent="Ready for a query";$("#results").innerHTML=`<div class="empty-state"><span aria-hidden="true">§</span><h3>Start with a passage or exact phrase.</h3><p>The workbench will show exact text and an inspectable evidence trail.</p></div>`;}

$("#query-form").addEventListener("submit",async(event)=>{event.preventDefault();const button=$("#study-button"),input=$("#study-query").value.trim();button.disabled=true;button.textContent="Studying…";$("#live-status").textContent="Search in progress";try{const result=await execute(input);state.lastRecord={recordVersion:"1.0.0",createdAt:new Date().toISOString(),query:{mode:state.mode,input},response:result};renderResult(result);}catch(error){console.error(error);renderError(error);}finally{button.disabled=false;button.textContent="Study";}});
$("#export-button").addEventListener("click",()=>{if(!state.lastRecord)return;const blob=new Blob([JSON.stringify(state.lastRecord,null,2)+"\n"],{type:"application/json"});const url=URL.createObjectURL(blob),anchor=document.createElement("a");anchor.href=url;anchor.download="kjv-research-record.json";anchor.click();URL.revokeObjectURL(url);});

async function execute(input){switch(state.mode){case"reference":return passage(input);case"exact-word":return exactWord(input,100);case"exact-phrase":return exactPhrase(input,100);case"related":return related(input,{limit:50,testament:$("#testament")?.value,book:$("#book")?.value,matchLevel:state.matchLevel});case"compare":return compare(input);case"graph":return graph(input);case"workflow":return workflow(input,$("#workflow").value);case"topic":return topic(input);default:throw new Error("Unknown mode");}}
function passage(input){const range=parseReference(input),start=state.verses.findIndex(v=>compareRefs(v.reference,range.start)===0),end=state.verses.findIndex(v=>compareRefs(v.reference,range.end)===0);if(start<0||end<0)throw new Error(`Unknown corpus reference: ${input}`);const context=state.verses.slice(Math.max(0,start-2),Math.min(state.verses.length,end+3)).map(v=>({...v,label:label(v.reference),requested:v.id>=start&&v.id<=end}));return{kind:"reference",meta:meta([`reference:${input}`,"context:2"]),data:{reference:input,requested:state.verses.slice(start,end+1),context}};}
function exactWord(input,limit=500){const tokens=tokenize(input);if(tokens.length!==1)throw new Error("Exact word search requires exactly one token");const key=tokens[0].folded,posting=state.indexes.word.get(key)||new Map();const matches=[...posting.entries()].map(([id,positions])=>({reference:state.verses[id].reference,label:label(state.verses[id].reference),displayText:state.verses[id].displayText,positions:[...positions]}));return{kind:"exact",meta:meta([`token:${key}`,"caseSensitive:false"]),data:{query:input,total:matches.length,totalOccurrences:matches.reduce((n,m)=>n+m.positions.length,0),matches:matches.slice(0,limit),distribution:{verseFrequency:matches.length,totalFrequency:matches.reduce((n,m)=>n+m.positions.length,0),firstMention:matches[0]?.reference||null,lastMention:matches.at(-1)?.reference||null}}};}
function exactPhrase(input,limit=500){const keys=tokenize(input).map(t=>t.folded);if(keys.length<2)throw new Error("Exact phrase search requires at least two tokens");const first=state.indexes.word.get(keys[0])||new Map(),matches=[];for(const id of first.keys()){const verse=state.verses[id],haystack=verse.tokens.map(t=>t.folded),starts=[];for(let i=0;i<=haystack.length-keys.length;i++)if(keys.every((key,j)=>haystack[i+j]===key))starts.push(i);if(starts.length)matches.push({reference:verse.reference,label:label(verse.reference),displayText:verse.displayText,startPositions:starts});}return{kind:"exact",meta:meta([`phrase:${keys.join(" ")}`,"caseSensitive:false"]),data:{query:input,total:matches.length,totalOccurrences:matches.reduce((n,m)=>n+m.startPositions.length,0),matches:matches.slice(0,limit)}};}

function related(input,options={}){const canonical=label(parseReference(input).start),sourceId=state.indexes.reference.get(canonical);if(sourceId===undefined)throw new Error(`Unknown corpus reference: ${input}`);const source=state.verses[sourceId],matchLevel=options.matchLevel||"exact_spelling",candidateIndex=matchLevel==="letter_exact"?state.indexes.surface:state.indexes.word,sourceKeys=matchingKeys(source,matchLevel),candidateIds=new Set();for(const token of new Set(sourceKeys))for(const id of candidateIndex.get(token)?.keys()||[])if(id!==sourceId)candidateIds.add(id);let candidates=[...candidateIds].map(id=>state.verses[id]).filter(v=>(!options.book||v.reference.book===options.book)&&(!options.testament||(options.testament==="OT"?v.reference.bookOrder<=39:v.reference.bookOrder>39)));let results=candidates.map(v=>scorePair(source,v,matchLevel)).sort(sortScores);if(options.minimumScore)results=results.filter(r=>r.score>=options.minimumScore);return{kind:"related",meta:meta([`reference:${canonical}`,`matchLevel:${matchLevel}`,`candidates:${candidates.length}`],matchLevel),data:{source:{label:canonical,displayText:source.displayText,reference:source.reference},candidateCount:candidates.length,results:results.slice(0,options.limit||50)}};}
function scorePair(source,target,matchLevel="exact_spelling"){const sourceTokens=matchingKeys(source,matchLevel),targetTokens=matchingKeys(target,matchLevel),sourceWords=[...new Set(sourceTokens)],targetWords=[...new Set(targetTokens)],shared=sourceWords.filter(t=>targetWords.includes(t)),union=[...new Set([...sourceWords,...targetWords])],weight=t=>Math.log((state.verses.length+1)/((state.stats.documentFrequency[t.toLowerCase()]||state.verses.length)+1))+1,intersection=shared.reduce((n,t)=>n+weight(t),0),unionWeight=union.reduce((n,t)=>n+weight(t),0),jaccard=clamp(intersection/(unionWeight||1)),phrases=findPhrases(source,target,matchLevel),phrase=clamp(phrases.reduce((n,p)=>n+p.tokens.length**2*p.multiplier,0)/25),rareTokens=shared.filter(t=>(state.stats.documentFrequency[t.toLowerCase()]||state.verses.length)<=state.stats.rareThreshold).map(token=>({token,documentFrequency:state.stats.documentFrequency[token.toLowerCase()]||state.verses.length,idf:round6(weight(token))})),rare=clamp(rareTokens.reduce((n,t)=>n+t.idf,0)/12),alignment=align(sourceTokens,targetTokens,new Set(shared)),order=orderScore(alignment,shared.length,sourceTokens.length,targetTokens.length),matchedTokens=alignment.map(pair=>{const a=source.tokens[pair.sourcePosition],b=target.tokens[pair.targetPosition],level=a.surface===b.surface?"case_exact":a.folded===b.folded?"case_folded":"normalized";return{...pair,sourceSurface:a.surface,targetSurface:b.surface,level};}),capitalizationEvidence=alignment.map(pair=>capitalizationItem(source,target,pair,weight)),capitalizationWeight=capitalizationEvidence.reduce((n,item)=>n+item.weight,0),capitalization=clamp(capitalizationWeight?capitalizationEvidence.reduce((n,item)=>n+item.weight*item.multiplier,0)/capitalizationWeight:0),components={jaccard:round6(jaccard),phrase:round6(phrase),rare:round6(rare),order:round6(order),capitalization:round6(capitalization),crossReference:0},score=round6(.4*jaccard+.2*phrase+.15*rare+.1*order+.1*capitalization);const phraseReason=phrases.some(p=>p.level==="case_exact")?"shared_exact_phrase":phrases.some(p=>p.level==="case_folded")?"shared_case_folded_phrase":phrases.length?"shared_normalized_phrase":null;return{reference:target.reference,label:label(target.reference),displayText:target.displayText,score,components,matchLevel,matchedTokens,matchedSurfaceTokens:[...new Set(matchedTokens.filter(item=>item.level==="case_exact").map(item=>item.sourceSurface))],matchedNormalizedTokens:shared,matchedPhrases:phrases,capitalizationEvidence,rareTokens,alignment,candidateReasons:[...(shared.length?["shared_nonzero_token"]:[]),...(phraseReason?[phraseReason]:[])],tieBreak:"score_desc → phrase_desc → rare_desc → jaccard_desc → canonical_order_asc",corpusVersion:CORPUS_VERSION,algorithmVersion:ALGORITHM_VERSION};}
function matchingKeys(verse,matchLevel){return matchLevel==="letter_exact"?verse.tokens.map(t=>t.surface):verse.tokens.map(t=>t.folded);}
function findPhrases(source,target,matchLevel){const a=matchingKeys(source,matchLevel),b=matchingKeys(target,matchLevel),found=[];for(let i=0;i<a.length;i++)for(let j=0;j<b.length;j++){let length=0;while(a[i+length]!==undefined&&a[i+length]===b[j+length])length++;if(length>=2){const offsets=Array.from({length},(_,k)=>k),level=offsets.every(k=>source.tokens[i+k].surface===target.tokens[j+k].surface)?"case_exact":offsets.every(k=>source.tokens[i+k].folded===target.tokens[j+k].folded)?"case_folded":"normalized",multiplier=level==="case_exact"?1:level==="case_folded"?.8:.5;found.push({tokens:source.tokens.slice(i,i+length).map(t=>t.surface),sourceStart:i,targetStart:j,level,multiplier});}}found.sort((x,y)=>y.tokens.length-x.tokens.length||x.sourceStart-y.sourceStart||x.targetStart-y.targetStart);const usedA=new Set(),usedB=new Set(),selected=[];for(const p of found){const ap=Array.from({length:p.tokens.length},(_,k)=>p.sourceStart+k),bp=Array.from({length:p.tokens.length},(_,k)=>p.targetStart+k);if(ap.some(x=>usedA.has(x))||bp.some(x=>usedB.has(x)))continue;ap.forEach(x=>usedA.add(x));bp.forEach(x=>usedB.add(x));selected.push(p);}return selected.sort((x,y)=>x.sourceStart-y.sourceStart);}
function capitalizationItem(source,target,pair,weight){const a=source.tokens[pair.sourcePosition],b=target.tokens[pair.targetPosition],aStart=isSentenceStart(source,pair.sourcePosition),bStart=isSentenceStart(target,pair.targetPosition);let multiplier=0,reason="different";if(a.surface===b.surface){multiplier=aStart||bStart?0.5:1;reason=aStart||bStart?"identical_sentence_start":"identical";}else if(a.folded===b.folded&&aStart!==bStart){multiplier=.25;reason="different_only_sentence_start";}return{token:pair.token,sourceSurface:a.surface,targetSurface:b.surface,sourcePosition:pair.sourcePosition,targetPosition:pair.targetPosition,multiplier,weight:round6(weight(a.folded)),reason};}
function isSentenceStart(verse,position){if(position===0)return true;const previous=verse.tokens[position-1],current=verse.tokens[position];return/[.!?][\s\])}"'’]*$/u.test(verse.displayText.slice(previous.charEnd,current.charStart));}
function align(a,b,shared){const result=[];let cursor=0;for(let i=0;i<a.length;i++){if(!shared.has(a[i]))continue;const j=b.indexOf(a[i],cursor);if(j<0)continue;result.push({token:a[i],sourcePosition:i,targetPosition:j});cursor=j+1;}return result;}
function orderScore(alignment,sharedCount,sourceLength,targetLength){if(!sharedCount||!alignment.length)return 0;const gaps=[];for(let i=1;i<alignment.length;i++){const previous=alignment[i-1],current=alignment[i],sourceGap=(current.sourcePosition-previous.sourcePosition)/Math.max(1,sourceLength-1),targetGap=(current.targetPosition-previous.targetPosition)/Math.max(1,targetLength-1);gaps.push(Math.abs(sourceGap-targetGap));}const mean=gaps.length?gaps.reduce((sum,value)=>sum+value,0)/gaps.length:0;return clamp((alignment.length/sharedCount)*(1/(1+mean)));}
function sortScores(a,b){return b.score-a.score||b.components.phrase-a.components.phrase||b.components.rare-a.components.rare||b.components.jaccard-a.components.jaccard||compareRefs(a.reference,b.reference);}const clamp=n=>Math.min(1,Math.max(0,n));const round6=n=>Math.round((n+Number.EPSILON)*1e6)/1e6;

function compare(input){const refs=input.split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean);if(refs.length<2||refs.length>10)throw new Error("Compare requires 2–10 references, one per line");const passages=refs.map(ref=>{const canonical=label(parseReference(ref).start),id=state.indexes.reference.get(canonical);if(id===undefined)throw new Error(`Unknown corpus reference: ${ref}`);return state.verses[id];});const common=[...new Set(passages[0].tokens.map(t=>t.folded))].filter(t=>passages.every(v=>v.tokens.some(x=>x.folded===t)));const pairs=[];for(let i=0;i<passages.length;i++)for(let j=i+1;j<passages.length;j++)pairs.push({source:label(passages[i].reference),target:label(passages[j].reference),explanation:scorePair(passages[i],passages[j])});return{kind:"compare",meta:meta([`references:${refs.join("|")}`]),data:{passages:passages.map(v=>({label:label(v.reference),displayText:v.displayText})),commonNormalizedTokens:common,pairs}};}
function graph(input){const base=related(input,{limit:10}),source=base.data.source,nodes=[{id:source.label,type:"verse",label:source.label}];const nodeMap=new Map([[source.label,nodes[0]]]),edges=[];for(const row of base.data.results){if(!nodeMap.has(row.label)){const n={id:row.label,type:"verse",label:row.label};nodeMap.set(row.label,n);nodes.push(n);}edges.push({source:source.label,target:row.label,type:"lexical_similarity",score:row.score,explanation:row});for(const term of row.matchedNormalizedTokens.slice(0,8)){const id=`term:${term}`;if(!nodeMap.has(id)){const n={id,type:"term",label:term};nodeMap.set(id,n);nodes.push(n);}edges.push({source:source.label,target:id,type:"contains_term",score:1,term});edges.push({source:id,target:row.label,type:"contains_term",score:1,term});}}const bounded=nodes.slice(0,30),kept=new Set(bounded.map(node=>node.id));return{kind:"graph",meta:base.meta,data:{source,nodes:bounded,edges:edges.filter(edge=>kept.has(edge.source)&&kept.has(edge.target))}};}
function workflow(input,type){if(type==="candidate_mates"){const result=related(input,{limit:20});return{...result,kind:"workflow",data:{type,title:"Candidate mates",notice:"Candidates reuse deterministic algorithm 1.1.0.",rows:result.data.results}};}if(type==="lexical_witnesses"){const result=related(input,{limit:100}),seen=new Set(),rows=[];for(const row of result.data.results)if(!seen.has(row.reference.book)){seen.add(row.reference.book);rows.push(row);if(rows.length===2)break;}return{kind:"workflow",meta:result.meta,data:{type,title:"Two lexical witnesses",notice:"Distinct canonical books are a lexical-independence heuristic, not a theological conclusion.",rows}};}const exact=exactWord(input,500);if(type==="divide_term"){const groups=new Map();for(const match of exact.data.matches){let group=groups.get(match.reference.book);if(!group){group={book:match.reference.book,verseCount:0,occurrenceCount:0,examples:[]};groups.set(match.reference.book,group);}group.verseCount++;group.occurrenceCount+=match.positions.length;if(group.examples.length<3)group.examples.push(match);}return{kind:"workflow",meta:exact.meta,data:{type,title:"Divide term by book",notice:"Groups are observed canonical-book contexts, not inferred senses.",groups:[...groups.values()]}};}return{kind:"workflow",meta:exact.meta,data:{type,title:type==="first_mention_chain"?"First-mention chain":"Gather mentions",notice:"Occurrences are exact normalized-token evidence in canonical order.",rows:type==="first_mention_chain"?exact.data.matches.slice(0,12):exact.data.matches}};}

async function topic(input){const exact=tokenize(input).length===1?exactWord(input,500):exactPhrase(input,500);if(exact.data.total)return{...exact,kind:"topic",data:{status:"exact_kjv",topic:input,exact:exact.data,notice:"The query occurs in the KJV, so no external vocabulary bridge was used."}};const snapshot=await lookupWordNet(input);return{kind:"topic",meta:meta([`topic:${input}`,"bridge:requires_sense_selection"]),data:{status:"requires_sense_selection",topic:input,snapshot,notice:"Choose a dictionary sense before any KJV vocabulary is suggested. WordNet is external evidence, not a biblical definition."}};}
async function lookupWordNet(headword){const normalized=headword.toLowerCase().replaceAll(" ","_");if(!state.wordnet){$("#live-status").textContent="Loading the external WordNet evidence layer";const positions=["noun","verb","adj","adv"];state.wordnet={};await Promise.all(positions.map(async pos=>{const [index,data]=await Promise.all([fetch(`./data/wordnet/index.${pos}`).then(requireOk).then(r=>r.text()),fetch(`./data/wordnet/data.${pos}`).then(requireOk).then(r=>r.text())]);state.wordnet[pos]={index:new Map(index.split(/\r?\n/).filter(line=>line&&!line.startsWith("  ")).map(line=>[line.slice(0,line.indexOf(" ")),line])),data:new Map(data.split(/\r?\n/).filter(Boolean).map(line=>[line.slice(0,8),line]))};}));}const senses=[];for(const [pos,bucket] of Object.entries(state.wordnet)){const line=bucket.index.get(normalized);if(!line)continue;const fields=line.trim().split(/\s+/),count=Number(fields[2]),pointers=Number(fields[3]),offsets=fields.slice(6+pointers,6+pointers+count);for(const offset of offsets){const row=bucket.data.get(offset);if(!row)continue;const divider=row.indexOf("|"),parts=row.slice(0,divider).trim().split(/\s+/),wordCount=parseInt(parts[3],16),synonyms=[];for(let i=0;i<wordCount;i++)synonyms.push(parts[4+i*2].replaceAll("_"," "));senses.push({id:`wn30:${parts[2]}:${offset}`,partOfSpeech:({noun:"noun",verb:"verb",adj:"adjective",adv:"adverb"})[pos],definition:row.slice(divider+1).trim().split(/;\s*"/,1)[0],synonyms});}}if(!senses.length)throw new Error(`Princeton WordNet has no entry for ${headword}.`);return{provider:"Princeton WordNet",providerVersion:"3.0",sourceUrl:WORDNET_SOURCE,license:WORDNET_LICENSE,headword,senses};}

function renderResult(result){$("#result-title").textContent=MODES[state.mode];$("#export-button").disabled=false;$("#live-status").textContent="Search complete";const interpretation=`<div class="interpretation"><span>Parsed deterministically</span><code>${esc(result.meta.queryTrace.join(" · "))}</code><small>${CORPUS_VERSION} / algorithm ${ALGORITHM_VERSION}</small></div>`;let body="";if(result.kind==="reference")body=renderPassage(result.data);else if(result.kind==="exact")body=renderExact(result.data);else if(result.kind==="related")body=renderRelated(result.data);else if(result.kind==="compare")body=renderCompare(result.data);else if(result.kind==="graph")body=renderGraph(result.data);else if(result.kind==="workflow")body=renderWorkflow(result.data);else if(result.kind==="topic")body=renderTopic(result.data);$("#results").innerHTML=interpretation+body;bindTopicActions(result);}
function renderPassage(data){return`<section><div class="section-title"><h3>${esc(data.reference)}</h3><span>${data.requested.length} requested verse${data.requested.length===1?"":"s"}</span></div><ol class="passage-context">${data.context.map(v=>`<li class="${v.requested?"requested":""}"><strong>${esc(v.label)}</strong><p>${esc(v.displayText)}</p></li>`).join("")}</ol></section>`;}
function renderExact(data){const d=data.distribution;return`<section>${d?`<div class="stat-grid"><div class="stat"><span>Verse frequency</span><strong>${d.verseFrequency}</strong></div><div class="stat"><span>Total occurrences</span><strong>${d.totalFrequency}</strong></div><div class="stat"><span>First mention</span><strong>${d.firstMention?esc(label(d.firstMention)):"—"}</strong></div><div class="stat"><span>Last mention</span><strong>${d.lastMention?esc(label(d.lastMention)):"—"}</strong></div></div>`:""}<div class="section-title"><h3>${data.total} matching verses</h3><span>${data.totalOccurrences} occurrences</span></div>${matchTable(data.matches)}</section>`;}
function matchTable(rows){return`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Exact text</th><th>Positions</th></tr></thead><tbody>${rows.map(m=>`<tr><th>${esc(m.label||label(m.reference))}</th><td>${esc(m.displayText)}</td><td><code>${esc((m.positions||m.startPositions||[]).join(", "))}</code></td></tr>`).join("")}</tbody></table></div>`;}
function renderRelated(data){let rows=data.results;const minimum=Number($("#minimum-score")?.value||0),evidence=$("#evidence")?.value;rows=rows.filter(r=>r.score>=minimum&&(!evidence||r.candidateReasons.includes(evidence)));return`<section><blockquote><strong>${esc(data.source.label)}</strong><p>${esc(data.source.displayText)}</p></blockquote><div class="section-title"><h3>${rows.length} ranked results</h3><span>${data.candidateCount} candidates evaluated</span></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Passage</th><th>Score</th><th>Evidence</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><th><span class="reference">${esc(r.label)}</span><p>${esc(r.displayText)}</p></th><td><strong>${r.score.toFixed(6)}</strong></td><td><details><summary>Why this matched</summary><dl class="evidence-list"><dt>Strictness</dt><dd>${esc(r.matchLevel.replaceAll("_"," "))}</dd><dt>Matched words</dt><dd>${esc(r.matchedTokens.map(t=>`${t.sourceSurface} ↔ ${t.targetSurface} (${t.level.replaceAll("_"," ")})`).join(", ")||"None")}</dd><dt>Phrase tiers</dt><dd>${esc(r.matchedPhrases.map(p=>`${p.tokens.join(" ")} (${p.level.replaceAll("_"," ")} × ${p.multiplier})`).join("; ")||"None")}</dd><dt>Capitalization</dt><dd>${esc(r.capitalizationEvidence.map(t=>`${t.sourceSurface} ↔ ${t.targetSurface}: ${t.multiplier}`).join(", ")||"None")}</dd><dt>Rare words</dt><dd>${esc(r.rareTokens.map(t=>`${t.token} (df ${t.documentFrequency})`).join(", ")||"None")}</dd><dt>Tie-break</dt><dd>${esc(r.tieBreak)}</dd></dl></details></td></tr>`).join("")}</tbody></table></div></section>`;}
function renderCompare(data){return`<section><div class="comparison-grid">${data.passages.map(p=>`<blockquote><strong>${esc(p.label)}</strong><p>${esc(p.displayText)}</p></blockquote>`).join("")}</div><div class="status-card"><strong>Common normalized tokens</strong><span>${esc(data.commonNormalizedTokens.join(", ")||"None")}</span></div><div class="table-wrap"><table><thead><tr><th>Pair</th><th>Score</th><th>Shared phrases</th></tr></thead><tbody>${data.pairs.map(p=>`<tr><th>${esc(p.source)} ↔ ${esc(p.target)}</th><td>${p.explanation.score.toFixed(6)}</td><td>${esc(p.explanation.matchedPhrases.map(x=>x.tokens.join(" ")).join("; ")||"None")}</td></tr>`).join("")}</tbody></table></div></section>`;}
function renderGraph(data){return`<section><blockquote><strong>${esc(data.source.label)}</strong><p>${esc(data.source.displayText)}</p></blockquote><div class="section-title"><h3>${data.nodes.length} evidence nodes</h3><span>${data.edges.length} explained edges</span></div><div class="graph-grid">${data.nodes.map(n=>`<div class="graph-node ${n.type}"><span class="pill">${esc(n.type)}</span><strong>${esc(n.label)}</strong></div>`).join("")}</div><div class="table-wrap"><table><thead><tr><th>From</th><th>To</th><th>Evidence</th></tr></thead><tbody>${data.edges.map(e=>`<tr><td>${esc(e.source)}</td><td>${esc(e.target)}</td><td>${esc(e.type)}${e.term?`: ${esc(e.term)}`:` · ${e.score.toFixed(6)}`}</td></tr>`).join("")}</tbody></table></div></section>`;}
function renderWorkflow(data){if(data.groups)return`<section><div class="status-card">${esc(data.notice)}</div>${data.groups.map(g=>`<details><summary>${esc(g.book)} · ${g.verseCount} verses · ${g.occurrenceCount} occurrences</summary>${g.examples.map(x=>`<blockquote><strong>${esc(x.label)}</strong><p>${esc(x.displayText)}</p></blockquote>`).join("")}</details>`).join("")}</section>`;const rows=data.rows||[];return`<section><div class="status-card">${esc(data.notice)}</div><div class="section-title"><h3>${esc(data.title)}</h3><span>${rows.length} results</span></div>${rows[0]?.score!==undefined?renderRelated({source:{label:"Workflow",displayText:"Deterministic lexical evidence"},candidateCount:rows.length,results:rows}):matchTable(rows)}</section>`;}
function renderTopic(data){if(data.status==="exact_kjv")return`<section><div class="status-card">${esc(data.notice)}</div>${renderExact(data.exact)}</section>`;return`<section><div class="status-card"><strong>External dictionary evidence</strong><span>${esc(data.notice)}</span><small>${esc(data.snapshot.provider)} ${esc(data.snapshot.providerVersion)} · ${esc(data.snapshot.license)}</small></div><fieldset id="sense-list"><legend>Choose one dictionary sense</legend>${data.snapshot.senses.map((s,i)=>`<label><input type="radio" name="sense" value="${i}"> <strong>${esc(s.partOfSpeech)}</strong> — ${esc(s.definition)}</label>`).join("<br>")}<button id="use-sense" type="button">Show candidate KJV words</button></fieldset><div id="topic-next"></div></section>`;}
function bindTopicActions(result){if(result.kind!=="topic"||result.data.status!=="requires_sense_selection")return;$("#use-sense").addEventListener("click",()=>{const checked=document.querySelector('input[name="sense"]:checked');if(!checked){$("#topic-next").innerHTML='<div class="error-card">Choose a sense first.</div>';return;}const sense=result.data.snapshot.senses[Number(checked.value)],candidates=[...new Set(sense.synonyms.map(s=>tokenize(s)).filter(t=>t.length===1).map(t=>t[0].folded))].filter(t=>state.stats.documentFrequency[t]).sort();if(!candidates.length){$("#topic-next").innerHTML='<div class="status-card">No single-word synonym from this external sense occurs in the KJV corpus.</div>';return;}$("#topic-next").innerHTML=`<fieldset><legend>Select candidate KJV vocabulary</legend>${candidates.map(c=>`<label><input type="checkbox" name="candidate" value="${esc(c)}"> ${esc(c)} (${state.stats.documentFrequency[c]} verses)</label>`).join("<br>")}<button id="run-candidates" type="button">Search selected words</button></fieldset>`;$("#run-candidates").addEventListener("click",()=>{const selected=[...document.querySelectorAll('input[name="candidate"]:checked')].map(x=>x.value);if(!selected.length)return;const rows=selected.flatMap(term=>exactWord(term,100).data.matches.map(m=>({...m,winningTerm:term})));$("#topic-next").innerHTML=`<div class="status-card">External bridge selected by the user. Dictionary confidence does not affect Scripture ranking.</div><div class="section-title"><h3>${rows.length} exact-KJV results</h3><span>${esc(selected.join(", "))}</span></div>${matchTable(rows)}`;});});}
function renderError(error){$("#result-title").textContent="Study error";$("#results").innerHTML=`<div class="error-card" role="alert"><strong>Could not complete the study.</strong><span>${esc(error.message||error)}</span></div>`;$("#live-status").textContent=`Search error: ${error.message||error}`;}

initialize();
